/* Independent behavior-review prototype. No model calls, credentials or upstream code. */
(() => {
'use strict';
const KEY='collab-replica-v5';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const clone=v=>JSON.parse(JSON.stringify(v));
const fresh=()=>({version:5,view:'chat',tab:'runs',members:[
{id:'lin',name:'林',alias:'lin',role:'方案与复核',runtime:'claude',model:'默认模型',binding:'follow',enabled:true},
{id:'xu',name:'序',alias:'xu',role:'实现与验证',runtime:'codex',model:'默认模型',binding:'follow',enabled:true},
{id:'zhi',name:'知',alias:'zhi',role:'资料与分析',runtime:'api',model:'自定义模型',binding:'follow',enabled:true}],
accounts:[{id:'claude-demo',name:'Claude 本机身份',family:'claude',kind:'cli',status:'unverified'},{id:'codex-demo',name:'Codex 本机身份',family:'codex',kind:'cli',status:'unverified'},{id:'api-demo',name:'API 示例连接',family:'api',kind:'api',status:'unverified',endpoint:'https://example.com/v1'}],
defaults:{claude:'claude-demo',codex:'codex-demo',api:'api-demo'},workspace:{path:'',connected:false},settings:{},threads:[],current:null,disposition:'queue',showArchived:false});
let state;try{state=JSON.parse(localStorage.getItem(KEY));}catch{}
if(state?.version!==5)state=fresh();
let groups=[],suppressed=new Map(),draft='',attachments=[],replyTo=null,toastTimer;
const thread=()=>state.threads.find(t=>t.id===state.current);
const member=id=>state.members.find(m=>m.id===id);
const label=id=>member(id)?.name||({user:'你',system:'系统'}[id]||id);
const account=m=>state.accounts.find(a=>a.id===(m.binding==='follow'?state.defaults[m.runtime]:m.binding));
const busy=(t,id)=>t.runs.find(r=>r.member===id&&['running','stopping'].includes(r.status));
const enabled=()=>state.members.filter(m=>m.enabled);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{document.querySelector('#storage-note')?.replaceChildren('本页内存模式：浏览器不允许保存');}}
function commit(){save();render();}
function notify(text){clearTimeout(toastTimer);document.querySelector('#toast')?.remove();const e=document.createElement('div');e.id='toast';e.className='toast';e.textContent=text;document.body.append(e);toastTimer=setTimeout(()=>e.remove(),4500);}
function event(t,title,detail){t.events.push({id:uid(),title,detail,at:new Date().toLocaleTimeString('zh-CN')});}
function newThread(title='新会话'){const t={id:uid(),title,pinned:false,archived:false,messages:[],queue:[],runs:[],tasks:[],events:[],lastExplicit:[],recent:null,defaultMember:enabled()[0]?.id,participants:enabled().map(m=>m.id),workspace:clone(state.workspace),seq:0,ball:{holder:null,status:'new',reason:'尚无明确责任事件'}};state.threads.push(t);state.current=t.id;state.view='chat';state.tab='runs';draft='';attachments=[];replyTo=null;return t;}
if(!thread())newThread('开始一次协作');
function parseMentions(text,t){
 const matches=[];const clean=text.replace(/```[\s\S]*?```|`[^`]*`/g,'');
 for(const hit of clean.matchAll(/(^|[\s,，.。!！?？、:：;；（(“‘"'])@([^\s,，.。!！?？、:：;；（）()“”‘’"']+)/g)){
  const token=hit[2].toLowerCase();let ids=[];
  if(['all','全体','全部'].includes(token))ids=state.members.map(m=>m.id);
  else if(['thread','本帖'].includes(token))ids=t.participants;
  else ids=state.members.filter(m=>[m.name.toLowerCase(),m.alias.replace(/^@/,'').toLowerCase()].includes(token)).map(m=>m.id);
  ids.forEach(id=>{if(!matches.includes(id))matches.push(id);});
 }return matches;
}
function route(text,t=thread()){
 const explicit=parseMentions(text,t);const available=id=>member(id)?.enabled;
 const unavailable=explicit.filter(id=>!available(id));if(explicit.some(available))return {targets:explicit.filter(available),explicit,reason:'本条明确点名',unavailable};
 const recent=t.lastExplicit.find(available);if(recent)return {targets:[recent],explicit,unavailable,reason:'最近点名中的首个可用成员'};
 if(available(t.recent))return {targets:[t.recent],explicit,unavailable,reason:'最近成功回复的成员'};
 const fallback=[t.defaultMember,...t.participants,...enabled().map(m=>m.id)].find(available);
 return {targets:fallback?[fallback]:[],explicit,unavailable,reason:'会话偏好 / 可用参与者'};
}
function addMessage(t,sender,body,options={}){const msg={id:uid(),sender,body,at:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),targets:[],...options};t.messages.push(msg);return msg;}
function enqueue(t,msg,targets,origin='user',groupId=null){targets.forEach(id=>{t.queue.push({id:uid(),message:msg.id,target:id,origin,position:++t.seq,priority:'normal',at:Date.now(),status:'queued',group:groupId});if(!t.participants.includes(id))t.participants.push(id);});}
function drain(t){const blocked=new Set();const entries=t.queue.filter(q=>q.status==='queued').sort((a,b)=>a.position-b.position||(a.priority==='urgent'?-1:1)-(b.priority==='urgent'?-1:1)||a.at-b.at||a.id.localeCompare(b.id));
 for(const q of entries){if(!member(q.target)?.enabled){q.reason='成员已停用';blocked.add(q.target);continue;}if(blocked.has(q.target)||busy(t,q.target)){q.reason='该成员仍在执行';blocked.add(q.target);continue;}if(q.origin==='agent'&&(suppressed.get(t.id)||0)>Date.now()){q.reason='取消后的短期自动续跑抑制';blocked.add(q.target);continue;}
  const m=member(q.target),a=account(m);const id=uid();q.status='running';q.run=id;q.reason='';const input=t.messages.filter(x=>!x.privateTo||x.privateTo===m.id).map(x=>({id:x.id,sender:x.sender,representation:'full',phase:'prepared',ownership:x.id===q.message?'assigned':'background'}));
  t.runs.push({id,member:m.id,status:'running',queue:q.id,group:q.group,source:q.message,snapshot:{name:m.name,runtime:m.runtime,model:m.model,account:a?.name||'未绑定',accountId:a?.id,accountStatus:a?.status||'unverified',workspace:t.workspace.path||'尚未接入工作区'},input,session:uid(),continuity:'unknown',approval:null});
  event(t,'开始模拟执行',`${label(m.id)} · ${id.slice(0,8)} · 配置已冻结。输入 prepared；没有真实 provider 接受证据。`);
 }}
function send(text){const t=thread();if(!text.trim()&&!attachments.length)return;const r=route(text,t);if(!r.targets.length){notify('没有可用接收者，请在成员设置中启用成员。');return;}const msg=addMessage(t,'user',text,{targets:r.targets,attachments:clone(attachments),replyTo,routeReason:r.reason});if(r.explicit.length)t.lastExplicit=r.explicit;
 for(const target of r.targets){const run=busy(t,target);if(state.disposition==='steer'&&run&&['codex','claude'].includes(run.snapshot.runtime)){const q={id:uid(),message:msg.id,target,origin:'user',position:++t.seq,priority:'normal',at:Date.now(),status:'append_unknown',run:run.id};t.queue.push(q);event(t,'模拟精确追加',`${label(target)} · ${run.id.slice(0,8)} · 接受不明，等待同一执行对账。`);}else enqueue(t,msg,[target]);}
 if(r.unavailable?.length)event(t,'目标不可用',r.unavailable.map(label).join('、'));draft='';attachments=[];replyTo=null;drain(t);commit();}
function finish(t,r,body='本轮模拟回复已结束。你可以继续补充，或在检查面板观察协作事件。'){
 if(r.status!=='running'||(r.approval&&r.approval.status==='pending'))return;
 r.status='done';r.teardown=true;t.queue.find(q=>q.id===r.queue).status='done';addMessage(t,r.member,body,{kind:'reply',run:r.id});t.recent=r.member;r.input.forEach(x=>x.phase='terminal');
 if(r.group){const g=groups.find(x=>x.id===r.group);if(g&&['running','partial'].includes(g.status)){g.status='partial';g.results[r.member]=body;g.targetStates[r.member]='responded';if(g.targets.every(x=>g.results[x])){g.status='done';addMessage(t,'system',g.targets.map(x=>`${label(x)}：${g.results[x]}`).join('\n'),{kind:'group-summary',group:g.id});event(t,'多人汇总已发布','mentions=[]；汇总本身不唤醒发起者。');}}else event(t,'组已终结或不可恢复','本轮消息仍保留；迟到结果不重开原聚合组。');}
 drain(t);commit();
}
function requestHandoff(t,task,to){if(!task||!to||task.owner===to)return;if(task.status==='done'){notify('已完成任务不能直接转交，请先重新打开。');return;}const r=t.runs.find(x=>x.id===task.execution);task.handoff={to,expected:task.ownerRevision,run:r?.id||null,status:r&&!r.teardown?'waiting_release':'prepared'};event(t,'正式转交准备',`${label(task.owner)} → ${label(to)} · expectedOwnerRevision=${task.ownerRevision}。绑定任务的精确执行；不要求目标先接受。`);commit();}
function applyHandoff(t,task){const h=task?.handoff;if(!h)return;if(h.expected!==task.ownerRevision||task.status==='done'){notify('责任版本或任务状态冲突，重新准备交接。');return;}const old=t.runs.find(r=>r.id===h.run);if(old&&!old.teardown){notify('旧执行尚未释放；请求停止不等于退出。');return;}task.owner=h.to;task.ownerRevision++;task.execution=null;task.handoff=null;event(t,'责任已转交',`${task.title} · ${label(task.owner)} · ownerRevision=${task.ownerRevision}`);commit();}
const icons={chat:'◌',members:'♧',accounts:'◎',workspace:'▧',guide:'◇'};
const viewNames={chat:'持续会话',members:'成员与运行时',accounts:'账户与登录',workspace:'项目与材料',guide:'复刻范围'};
function btn(action,text,attrs='',cls=''){return `<button data-action="${action}" class="${cls}" ${attrs}>${text}</button>`;}
function render(){const t=thread();const root=document.querySelector('#app');const visible=state.threads.filter(x=>x.archived===state.showArchived).sort((a,b)=>Number(b.pinned)-Number(a.pinned));
 root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">m</span><div>协作之间<small>Multi-Agent workspace</small></div></div><div class="sidebar-label">工作空间 <span class="badge">原型 v5</span></div><nav>${['chat','members','accounts','workspace','guide'].map(v=>btn('nav',`${icons[v]} <span>${viewNames[v]}</span>`,`data-view="${v}"`,state.view===v?'active':'')).join('')}</nav><div class="sidebar-label">${state.showArchived?'归档会话':'我的会话'} ${btn('new-thread','＋','aria-label="新建会话"')}</div><input id="thread-search" placeholder="查找会话" aria-label="查找会话"><div class="thread-list">${visible.map(x=>btn('select-thread',`${x.pinned?'⌁ ':''}${esc(x.title)}`,`data-id="${x.id}"`,x.id===t.id?'selected':'')).join('')||'<p class="muted">暂无会话</p>'}</div>${btn('toggle-archive',state.showArchived?'返回会话列表':'查看归档会话')}<div class="sidebar-foot"><span class="status-dot"></span> 离线交互评审<span id="storage-note">状态保存在此浏览器</span></div></aside><main><header class="topbar"><span>${viewNames[state.view]}</span><div class="toolbar"><span class="badge subtle">Clowder 行为基线 · c238b40a</span><span class="badge">模拟环境</span></div></header>${state.view==='chat'?chat(t):state.view==='guide'?guide():`<div class="settings-page">${window.ReplicaSettings.render(state,state.view)}</div>`}</main></div>`;
 document.querySelector('#message-input')?.addEventListener('input',e=>{draft=e.target.value;updatePreview();});
 document.querySelector('#thread-search')?.addEventListener('input',e=>document.querySelectorAll('[data-action="select-thread"]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase())));
 updatePreview();
}
function chat(t){return `<div class="conversation-head"><div><div class="eyebrow">${t.archived?'已归档':'公共会话'} · ${t.participants.filter(id=>member(id)?.enabled).length} 位成员</div><h1>${esc(t.title)}</h1><p class="muted">${esc(t.workspace.path||'尚未连接项目')} · 无需预先创建任务，直接开始交流</p></div><div class="toolbar">${btn('rename-thread','重命名')}${btn('pin-thread',t.pinned?'取消置顶':'置顶')}${btn('archive-thread',t.archived?'恢复会话':'归档')}</div></div><div class="workspace-layout"><section class="conversation"><div class="member-strip">${enabled().map(m=>`<span class="member-chip"><span class="avatar ${m.runtime}">${esc(m.name.slice(0,1))}</span>${esc(m.name)} <small>${m.runtime==='claude'?'Claude Code':m.runtime==='codex'?'Codex':'API'}</small><i class="${busy(t,m.id)?'working':''}"></i></span>`).join('')}</div><div class="messages" id="messages">${t.messages.length?t.messages.map(messageHtml).join(''):`<div class="welcome"><span class="welcome-mark">◌</span><h2>让协作从一句话开始</h2><p>直接发送目标，或用 @成员指定接收者。<br>每位成员保留独立执行状态，共享可见的会话材料。</p><div class="suggestions">${btn('example','讨论一个产品方案','data-text="请一起讨论一个本地笔记工具的方案"')}${btn('example','请两位成员参与','data-text="@林 @序 请检查这个方案的实现边界"')}</div><p class="muted small">原型只模拟投递与运行事件，不会理解或执行任意任务。</p></div>`}</div><div class="composer-area">${replyTo?`<div class="quote-bar">引用：${esc(t.messages.find(m=>m.id===replyTo)?.body.slice(0,80))}${btn('clear-reply','×','aria-label="取消引用"')}</div>`:''}${attachments.length?`<div class="quote-bar">${attachments.map(a=>esc(a.name)).join('、')} ${btn('clear-files','移除')}</div>`:''}<form id="composer"><textarea id="message-input" rows="3" maxlength="12000" placeholder="发消息，@成员指定接收者…" aria-label="消息内容" ${t.archived?'disabled':''}>${esc(draft)}</textarea><div class="composer-bottom"><details class="add-menu"><summary>＋</summary><div class="add-pop"><label class="upload">添加文件（仅元数据）<input type="file" id="file-input" multiple></label><label class="field">运行中输入偏好<select id="disposition"><option value="queue" ${state.disposition==='queue'?'selected':''}>排队等待</option><option value="steer" ${state.disposition==='steer'?'selected':''}>引导当前回复（按承载能力）</option></select></label><p class="muted small">可选偏好，会记住。无需每条消息选择。</p></div></details><span id="route-preview" class="muted small"></span><button class="primary" type="submit" ${t.archived?'disabled':''}>发送 ↑</button></div></form><div class="composer-note">⌘ / Ctrl + Enter 发送 · 模拟运行，不发送网络请求</div></div></section><aside class="inspector"><div class="tabs">${[['runs','运行'],['tasks','任务'],['queue','队列'],['context','上下文'],['events','记录']].map(([v,n])=>btn('tab',n,`data-tab="${v}"`,state.tab===v?'active':'')).join('')}</div><div class="inspector-body">${({runs:()=>runsHtml(t),tasks:()=>tasksHtml(t),queue:()=>queueHtml(t),context:()=>contextHtml(t),events:()=>eventsHtml(t)})[state.tab]()}</div></aside></div>`;}
function messageHtml(m){return `<article class="message ${m.sender==='user'?'from-user':''}"><span class="avatar ${member(m.sender)?.runtime||''}">${esc(label(m.sender).slice(0,1))}</span><div class="message-content"><div class="message-meta"><b>${esc(label(m.sender))}</b><span>${m.at}</span>${m.kind?`<span class="badge subtle">${esc(({reply:'模拟回复',info:'仅知会',progress:'进展',a2a:'协作请求','group-summary':'多人汇总'})[m.kind]||m.kind)}</span>`:''}</div>${m.replyTo?'<div class="muted small">↳ 引用了会话中的一条消息</div>':''}<div class="message-text">${esc(m.body)}</div>${m.attachments?.length?`<div class="attachments">${m.attachments.map(a=>`<span>▤ ${esc(a.name)} · ${a.size} B</span>`).join('')}</div>`:''}${m.targets?.length?`<div class="muted small">投递给 ${m.targets.map(label).map(esc).join('、')}${m.routeReason?' · '+esc(m.routeReason):''}</div>`:''}<div class="message-actions">${btn('reply','引用',`data-id="${m.id}"`)}${btn('branch','从此处分支',`data-id="${m.id}"`)}</div></div></article>`;}
function updatePreview(){const e=document.querySelector('#route-preview');if(!e)return;const r=route(draft);e.textContent=`→ ${r.targets.map(label).join('、')||'无可用成员'} · ${r.reason}${r.unavailable?.length?' · 不可用：'+r.unavailable.map(label).join('、'):''}`;}
function runsHtml(t){const runs=t.runs.filter(r=>['running','stopping'].includes(r.status));return `<div class="panel-heading"><h3>当前执行</h3>${btn('cancel-all','全部停止','', 'danger')}</div><p class="muted small">真实产品自动产生事件。这里通过模拟按钮观察结果，任意正文不会触发预设关键词脚本。</p>${(suppressed.get(t.id)||0)>Date.now()?`<div class="notice">自动续跑暂时抑制，约 60 秒。不是持久任务暂停。${btn('expire-suppression','模拟 60 秒到期')}</div>`:''}${runs.length?runs.map(r=>runHtml(t,r)).join(''):'<div class="empty">没有执行中的成员<br><small>发送消息即可开始一次模拟执行</small></div>'}<details class="card"><summary>多人协作组 ${groups.filter(g=>g.thread===t.id).length}</summary>${groups.filter(g=>g.thread===t.id).map(g=>`<div class="group"><b>${esc(g.question)}</b><p class="muted">${g.status} · ${Object.keys(g.results).length}/${g.targets.length} 个结果</p><p class="small">汇总不自动回唤；超时不发布部分汇总。</p><p class="small">${g.targets.map(id=>`${esc(label(id))}：${g.targetStates[id]}`).join(' · ')}</p>${['running','partial'].includes(g.status)?btn('group-timeout','模拟组超时',`data-id="${g.id}"`):''}</div>`).join('')||'<p class="muted">从运行卡的 Agent 事件模拟器发起。</p>'}${btn('restart-aggregation','模拟聚合进程重启')}</details><details class="card"><summary>近期已结束执行</summary>${t.runs.filter(r=>!['running','stopping'].includes(r.status)).slice(-8).reverse().map(r=>`<p>${esc(r.snapshot.name)} · ${esc(r.status)} · ${r.id.slice(0,8)}</p>`).join('')||'<p class="muted">暂无</p>'}</details>`;}
function runHtml(t,r){const options=enabled().filter(m=>m.id!==r.member).map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('');return `<div class="card run-card" data-run="${r.id}"><div class="panel-heading"><h3>${esc(label(r.member))}</h3><span class="badge ${r.status==='running'?'green':''}">${r.status==='running'?'模拟运行中':'等待退出证据'}</span></div><p class="muted small">${esc(r.snapshot.runtime)} · ${esc(r.snapshot.model)}<br>${esc(r.snapshot.account)} · ${r.snapshot.accountStatus==='simulated'?'已模拟连接':'身份未验证'}</p><details><summary class="small">本轮配置与身份</summary><dl><dt>Invocation</dt><dd>${r.id}</dd><dt>项目</dt><dd>${esc(r.snapshot.workspace)}</dd><dt>会话续接</dt><dd>unknown · 无真实 provider 证据</dd></dl></details>${r.approval?`<div class="notice"><b>模拟工具审批</b><p>${esc(r.approval.title)}</p><small>绑定 ${r.id.slice(0,8)} · revision ${r.approval.revision}</small><p>状态：${r.approval.status}</p>${r.approval.status==='pending'?`${btn('approve','允许',`data-run="${r.id}"`)} ${btn('reject','拒绝',`data-run="${r.id}"`)}`:''}</div>`:''}<div class="toolbar">${r.status==='running'?`${btn('finish','完成模拟回复',`data-run="${r.id}"`,'primary')}${btn('stop','停止本轮',`data-run="${r.id}"`)}`:btn('release','模拟确认退出',`data-run="${r.id}"`,'primary')}</div>${r.status==='running'?`<details class="agent-lab"><summary>Agent 事件模拟器</summary><p class="muted small">代替模型回调，供评审；这些选项不出现在用户发送前。</p><label class="field">协作对象<select class="agent-target">${options}</select></label><label class="field">事件正文<textarea class="agent-body" rows="2">请协助检查实现边界</textarea></label><div class="button-grid">${btn('agent-info','无目标知会',`data-run="${r.id}"`)}${btn('agent-fyi','定向 FYI',`data-run="${r.id}"`)}${btn('agent-progress','发布进展',`data-run="${r.id}"`)}${btn('agent-dispatch','结构化派发',`data-run="${r.id}"`)}${btn('agent-text','文本接力（本轮结束）',`data-run="${r.id}" ${r.group?'disabled title="并行回复抑制文本接力"':''}`)}${btn('agent-group','多人征询',`data-run="${r.id}" ${r.group?'disabled title="组内执行不级联发起多人征询"':''}`)}${btn('agent-task','建立普通任务',`data-run="${r.id}"`)}${btn('agent-approval','请求工具审批',`data-run="${r.id}"`)}${btn('agent-artifact','提交模拟产物',`data-run="${r.id}"`)}</div></details>`:''}</div>`;}
function tasksHtml(t){return `<div class="panel-heading"><h3>可选任务</h3>${btn('new-task','＋ 新任务')}</div><p class="muted small">普通任务可由获授权成员标记完成；不强制每轮对话由用户验收。负责人独立于消息接收者与执行者。</p>${t.tasks.map(task=>`<div class="card"><h3>${esc(task.title)}</h3><p>${esc(label(task.owner))} · ownerRevision ${task.ownerRevision}</p><p class="badge">${task.status}</p><div class="toolbar">${btn('task-done','用户标记完成',`data-task="${task.id}"`)}${btn('task-agent-done','模拟绑定执行完成',`data-task="${task.id}" ${!task.execution?'disabled':''}`)}${btn('task-reopen','重新打开',`data-task="${task.id}"`)}</div><div class="field"><label>转交目标</label><select data-task-target="${task.id}">${enabled().filter(m=>m.id!==task.owner).map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div>${task.handoff?`<div class="notice">准备转交给 ${esc(label(task.handoff.to))}<p>预期版本 ${task.handoff.expected} · ${task.handoff.status}</p>${btn('apply-handoff','应用转交',`data-task="${task.id}"`)} ${btn('withdraw-handoff','撤销准备',`data-task="${task.id}"`)}</div>`:btn('prepare-handoff','准备转交',`data-task="${task.id}"`)}${btn('stale-task','模拟旧版本回调',`data-task="${task.id}"`)}</div>`).join('')||'<div class="empty">会话尚无任务<br><small>直接聊天无需建立任务</small></div>'}`;}
function queueHtml(t){return `<h3>消息队列</h3><p class="muted small">顺序：position → urgent/normal → 时间 → ID。忙碌只阻挡同目标；没有固定 2:1 配额。</p>${t.queue.map(q=>`<div class="card"><b>${esc(label(q.target))}</b> <span class="badge">${esc(q.status)}</span><p class="muted small">#${q.position} · ${q.origin} · ${q.priority}</p><p class="small">${esc(t.messages.find(m=>m.id===q.message)?.body.slice(0,100))}</p>${q.reason?`<p class="muted small">${esc(q.reason)}</p>`:''}${q.status==='queued'?`${btn('queue-up','移到前面',`data-id="${q.id}"`)} ${btn('queue-cancel','取消待办',`data-id="${q.id}"`)}`:''}${q.status==='append_unknown'?`<p class="small">精确运行 ${q.run.slice(0,8)} · 待对账，不创建第二份执行</p>${btn('append-accepted','模拟确认已接受',`data-id="${q.id}"`)} ${btn('append-rejected','模拟确认未接受',`data-id="${q.id}"`)}`:''}</div>`).join('')||'<div class="empty">暂无队列记录</div>'}`;}
function contextHtml(t){const r=t.runs.at(-1);return `<h3>输入与会话证据</h3><p class="muted small">本页从当前模拟运行实际绑定的消息生成。prepared / observed / terminal 不等价于模型理解。</p>${r?`<div class="card"><b>${esc(label(r.member))} · ${r.id.slice(0,8)}</b><dl><dt>Session</dt><dd>${r.session}</dd><dt>Continuity</dt><dd>${r.continuity}</dd><dt>Token / 费用</dt><dd>未知（未连接真实运行时）</dd><dt>原始 Prompt</dt><dd>未捕获</dd></dl>${btn('rebuild-session','模拟会话失效后重建',`data-run="${r.id}"`)}</div>${r.input.map(x=>`<div class="card small"><b>${esc(label(x.sender))}</b> · ${x.representation} · ${x.ownership}<p class="muted">${x.id.slice(0,8)} · ${x.phase}</p><p>${esc(t.messages.find(m=>m.id===x.id)?.body.slice(0,140))}</p></div>`).join('')}`:'<div class="empty">开始执行后查看实际选入的消息</div>'}`;}
function eventsHtml(t){const ball=t.ball||{holder:null,status:'new',reason:'尚无事件'};return `<div class="card"><h3>球权投影 · 模拟</h3><p>${esc(label(ball.holder||'尚无持球者'))} · ${ball.status}</p><p class="muted small">${esc(ball.reason)}。球权投影不等于普通任务 owner，也不释放执行槽。</p><label class="field">事件对象<select id="ball-target">${enabled().map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><div class="button-grid">${btn('ball-handed','转交球权')}${btn('ball-human','等待用户')}${btn('ball-dead','执行死亡')}${btn('ball-zombie','长期无活动')}${btn('ball-resolved','已解决')}</div></div><h3>协作记录</h3><p class="muted small">任务责任、当前执行和投递记录分别保存；不会把任一“正在发言者”当成固定负责人。</p>${t.events.slice().reverse().map(e=>`<div class="event"><small>${e.at}</small><b>${esc(e.title)}</b><p>${esc(e.detail)}</p></div>`).join('')||'<div class="empty">暂无事件</div>'}`;}
function guide(){return `<div class="settings-page"><div class="eyebrow">BEHAVIOR PARITY</div><h1>以真实行为为基线</h1><p class="lead">先复刻持续协作的使用方式，再独立实现承载与可靠性。</p><div class="notice">当前为离线评审原型。可修改配置与模拟协作；不调用模型、不登录官方账户、不读取密钥、不执行文件写入。</div><div class="grid"><div class="card"><h3>现在可以体验</h3><p>创建、切换、归档和分支会话；配置团队和账户；普通输入与 @ 路由；引用与附件元数据；协作派发、知会、任务交接、审批和队列；从消息派生上下文清单。</p></div><div class="card"><h3>已纠正的默认规则</h3><p>不按任务负责人自动改投。不强制交接接受或用户验收。不使用 2:1 调度。普通结果不保证自动回唤。取消不是持久暂停。多人聚合超时不自动汇总。</p></div><div class="card"><h3>仍需真实实现</h3><p>Codex / Claude Code / API 接入，凭据隔离与登录，数据库、回调鉴权、工具与进程恢复。模拟成功不能当成真实运行验收。</p></div><div class="card"><h3>完整范围已列入指导</h3><p>85 项逐条追踪；私聊、记忆治理、精确转发、外部等待、更多承载等分阶段实现。原型覆盖子集，未将全部功能标成已完成。</p></div></div><div class="toolbar"><a class="button" href="history/v4/prototype.html" target="_blank">查看 v4 历史设计</a>${btn('nav','返回工作台','data-view="chat"','primary')}</div></div>`;}
const api={esc,uid,notify,commit:()=>{if(state.view==='workspace')thread().workspace=clone(state.workspace);commit();},render};
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='composer')send(draft);else window.ReplicaSettings.submit(e.target,state,api);});
document.addEventListener('keydown',e=>{if(e.target.id==='message-input'&&(e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();send(draft);}});
document.addEventListener('change',e=>{if(e.target.id==='disposition'){state.disposition=e.target.value;save();}if(e.target.id==='file-input'){attachments=[...e.target.files].map(f=>({name:f.name,size:f.size,type:f.type||'unknown'}));render();}});
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,t=thread();
 if(a.startsWith('settings-')){window.ReplicaSettings.handle(a,el,state,api);return;}
 const r=t.runs.find(x=>x.id===el.dataset.run),task=t.tasks.find(x=>x.id===el.dataset.task),q=t.queue.find(x=>x.id===el.dataset.id);
 if(a.startsWith('ball-')){const current=t.ball||{holder:null,status:'new'};const allowed=a==='ball-dead'?['active','blocked']:a==='ball-zombie'?['active','blocked','parked','void']:a==='ball-human'?['new','active','blocked','parked','void','zombie']:null;if(allowed&&!allowed.includes(current.status)){notify('该事件不适用于当前球权状态，投影未改变。');return;}const holder=a==='ball-human'?'user':a==='ball-handed'?document.querySelector('#ball-target').value:current.holder;t.ball={holder,status:({'ball-handed':'active','ball-human':'parked','ball-dead':'dead','ball-zombie':'zombie','ball-resolved':'resolved'})[a],reason:'显式模拟事件 '+a};event(t,'球权投影变化',`${label(holder)} · ${t.ball.status}；任务 owner 与执行占用未改变。`);commit();return;}
 if(a==='nav'){state.view=el.dataset.view;commit();return;}if(a==='tab'){state.tab=el.dataset.tab;commit();return;}
 if(a==='new-thread'){newThread();commit();return;}if(a==='select-thread'){state.current=el.dataset.id;state.view='chat';draft='';attachments=[];replyTo=null;commit();return;}
 if(a==='toggle-archive'){state.showArchived=!state.showArchived;commit();return;}
 if(a==='rename-thread'){const v=prompt('会话名称',t.title);if(v?.trim())t.title=v.trim().slice(0,100);commit();return;}
 if(a==='pin-thread'){t.pinned=!t.pinned;commit();return;}
 if(a==='archive-thread'){t.archived=!t.archived;state.showArchived=t.archived;commit();return;}
 if(a==='example'){draft=el.dataset.text;render();document.querySelector('#message-input').focus();return;}
 if(a==='reply'){replyTo=el.dataset.id;render();document.querySelector('#message-input').focus();return;}
 if(a==='clear-reply'){replyTo=null;render();return;}if(a==='clear-files'){attachments=[];render();return;}
 if(a==='branch'){const index=t.messages.findIndex(m=>m.id===el.dataset.id);const n=newThread(t.title+' · 分支');n.messages=clone(t.messages.slice(0,index+1));n.parent={thread:t.id,message:el.dataset.id};n.lastExplicit=[];for(const m of n.messages)if(m.sender==='user'){const refs=parseMentions(m.body,n);if(refs.length)n.lastExplicit=refs;}event(n,'从消息分支','复制截止所选消息的可见记录；不复制活动执行和任务责任。');commit();return;}
 if(a==='finish'){finish(t,r);return;}if(a==='stop'){r.status='stopping';event(t,'请求停止',`${label(r.member)} · 等待精确执行退出证据。后续队列未被取消。`);commit();return;}
 if(a==='release'){r.status='cancelled';r.teardown=true;t.queue.find(x=>x.id===r.queue).status='cancelled';event(t,'模拟退出已确认',r.id);drain(t);commit();return;}
 if(a==='cancel-all'){t.runs.filter(x=>x.status==='running').forEach(x=>x.status='stopping');suppressed.set(t.id,Date.now()+60000);event(t,'全部停止','当前轮请求取消；短期抑制自动续跑，未设置持久业务暂停。');commit();return;}
 if(a==='expire-suppression'){suppressed.delete(t.id);drain(t);commit();return;}
 if(a==='queue-up'){q.position=Math.min(...t.queue.filter(x=>x.status==='queued').map(x=>x.position))-1;drain(t);commit();return;}
 if(a==='queue-cancel'){q.status='cancelled';drain(t);commit();return;}
 if(a==='append-accepted'){q.status='covered';const active=t.runs.find(x=>x.id===q.run);active.input.push({id:q.message,sender:'user',representation:'full',phase:'observed (模拟回执)',ownership:'assigned'});event(t,'模拟接受对账','完整正文归到精确执行，未另建待办。');commit();return;}
 if(a==='append-rejected'){q.status='queued';delete q.run;event(t,'模拟未接受对账','同一执行确认未接受，退回队列等待下一轮。');drain(t);commit();return;}
 if(a==='new-task'||a==='agent-task'){const title=a==='new-task'?prompt('普通任务名称'):r&&document.querySelector(`[data-run="${r.id}"].run-card .agent-body`).value;if(!title?.trim())return;t.tasks.push({id:uid(),title:title.trim(),owner:r?.member||route('').targets[0],ownerRevision:1,status:'todo',execution:r?.id||null,executionRevision:1,handoff:null});state.tab='tasks';event(t,'建立普通任务','任务责任不会改变普通聊天路由。');commit();return;}
 if(a==='task-done'||a==='task-agent-done'){if(a==='task-agent-done'){const bound=t.runs.find(x=>x.id===task.execution);if(!bound||bound.member!==task.owner||task.executionRevision!==task.ownerRevision||bound.status!=='running'||!member(bound.member)?.enabled){notify('执行身份或责任版本不匹配，拒绝完成回调。');return;}}task.status='done';event(t,'普通任务完成',a==='task-done'?'用户修改任务状态。':`${label(task.owner)} 的绑定执行回调（模拟），无需额外用户验收。`);commit();return;}
 if(a==='task-reopen'){task.status='todo';commit();return;}
 if(a==='prepare-handoff'){requestHandoff(t,task,document.querySelector(`[data-task-target="${task.id}"]`).value);return;}
 if(a==='apply-handoff'){applyHandoff(t,task);return;}
 if(a==='withdraw-handoff'){task.handoff=null;commit();return;}
 if(a==='stale-task'){event(t,'拒绝旧责任版本回调',`提交 ownerRevision=${task.ownerRevision-1}；当前=${task.ownerRevision}。任务未改变。`);commit();notify('旧版本回调已拒绝');return;}
 if(a==='rebuild-session'){r.session=uid();r.continuity='unknown';event(t,'模拟重建会话','保留业务消息与来源；ID 变化不证明 provider 已续接。');commit();return;}
 if(a==='approve'||a==='reject'){r.approval.status=a==='approve'?'approved':'rejected';event(t,'工具审批答复',`${r.id.slice(0,8)} · ${r.approval.status} · 不执行真实工具。`);commit();return;}
 if(a==='group-timeout'){const g=groups.find(x=>x.id===el.dataset.id);g.status='timeout';g.targets.filter(id=>!g.results[id]).forEach(id=>g.targetStates[id]='timeout');event(t,'多人组超时','缺席目标标记 timeout；不发布部分汇总，不回唤发起者。');commit();return;}
 if(a==='restart-aggregation'){groups=groups.filter(g=>g.thread!==t.id);event(t,'模拟聚合进程重启','内存中的组丢失；已投递的成员队列与公共消息仍保留。不声称可恢复汇总。');commit();return;}
 if(a.startsWith('agent-')&&r?.status==='running'){
 const card=el.closest('.run-card'),to=card.querySelector('.agent-target').value,body=card.querySelector('.agent-body').value.trim()||'协作事件';
 if(a==='agent-approval'){r.approval={id:uid(),title:'写入方案草稿（仅模拟，不写文件）',revision:1,status:'pending'};commit();return;}
 if(a==='agent-artifact'){addMessage(t,r.member,'模拟交付：方案草稿.md\n这是产物展示占位，没有真实文件或版本摘要。',{kind:'产物示意'});commit();return;}
 if(a==='agent-group'){if(r.group){notify('组内执行不能级联发起多人征询');return;}const targets=enabled().filter(m=>m.id!==r.member).map(m=>m.id);if(!targets.length){notify('需要至少一位其他成员');return;}const g={id:uid(),thread:t.id,from:r.member,targets,question:body,results:{},targetStates:Object.fromEntries(targets.map(id=>[id,'pending'])),status:'running'};groups.push(g);const msg=addMessage(t,r.member,body,{kind:'a2a',targets,group:g.id});enqueue(t,msg,targets,'agent',g.id);event(t,'创建多人征询','按当前会话上下文投递；不承诺冻结历史或盲审隔离。');drain(t);commit();return;}
 if(['agent-info','agent-progress'].includes(a)){addMessage(t,r.member,body,{kind:a==='agent-info'?'info':'progress',targets:[]});event(t,'公开消息','仅发表，不创建唤醒待办，不改变任务责任。');commit();return;}
 if(!to){notify('需要另一位可用成员');return;}
 // Simulated structured call and serial text handoff are explicit events, never inferred from user text.
 if(a==='agent-text'){if(r.group){notify('并行回复不触发文本接力');return;}r.status='done';r.teardown=true;t.queue.find(x=>x.id===r.queue).status='done';t.recent=r.member;}
 const content=a==='agent-text'?`@${member(to).alias.replace(/^@/,'')} ${body}`:body;const msg=addMessage(t,r.member,content,{kind:a==='agent-fyi'?'定向 FYI':'a2a',targets:[to]});enqueue(t,msg,[to],'agent');event(t,a==='agent-text'?'文本串行接力':'结构化并发派发',a==='agent-text'?'完整串行回复的行首 @ 触发。当前轮结束后目标进入队列。':a==='agent-fyi'?'普通成员的显式目标 FYI 仍可唤醒；稀缺订阅通知策略未在此原型模拟。':'发起者本轮可继续，空闲目标可立即启动。');drain(t);commit();return;
 }
});
setInterval(()=>{const t=thread();if(suppressed.has(t.id)&&suppressed.get(t.id)<=Date.now()){suppressed.delete(t.id);drain(t);commit();}},1000);
commit();
})();
